fn exec_turns_to_defeat(health: i8, strength: i8) -> i64 {
    // Convert to a wider type before arithmetic to avoid i8 overflow.
    let h = health as i64;
    let s = strength as i64;
    // With the given constraints, s >= 1, so division is safe.
    (h + s - 1) / s
}

